import type { ChangelogTexts } from '.';

const changelog: ChangelogTexts = {
  fixes1031:
    'Corrections\u202f: la promo du jour ne descend plus sous le prix de revente, et son étiquette indique la vraie réduction\u202f; comme pour l’Ichiban Kuji, l’arbre à vœux demande désormais un e-mail vérifié et un compte d’au moins 3 jours\u202f; les aliments du frigo ne sont vendus pour payer une dette qu’après 3 jours entiers de dette (sans compter le jour où elle a commencé)',
  events1031: 'Événements aléatoires\u202f: une nouvelle série d’événements',
  events1028:
    'Nouveau\u202f: événements aléatoires et quiz du village. Pendant que vous jouez, il peut se passer quelque chose d’inattendu dans votre restaurant (au plus une fois toutes les 4 heures)\u202f: certains événements donnent un petit bonus ou malus pendant 1 à 4 heures, d’autres vous laissent choisir entre deux options, et certains ont une suite quelques jours plus tard. Parfois, c’est une question du quiz du village, et une bonne réponse rapporte un bon mystère. Chaque jeudi soir, le bar organise une soirée quiz où trois bonnes réponses rapportent 3 bons. Les restaurants de niveau inférieur à 10 ne reçoivent jamais d’événement avec malus',
  pest1027:
    'Tapettes et insecticides revus\u202f: la Tapette à souris coûte 18\u202f000 pièces (30\u202f% de capture), la nouvelle Tapette en acier 36\u202f000 (45\u202f%) et la Tapette en or passe à 75\u202f% pour 90\u202f000\u202f; l’Insecticide anti-cafards ne change pas, le nouvel Insecticide de qualité coûte 13\u202f000 (35\u202f% d’élimination) et l’Insecticide en or passe à 55\u202f% pour 26\u202f000\u202f; le marché noir vend des versions à 99\u202f%\u202f: Piège au fromage (24 heures, 15 diamants\u202f; Océan de fromage, 120 heures, 72) et Tentation caramel (24 heures, 4 diamants\u202f; Festin de caramel, 120 heures, 17)\u202f; la Tapette longue durée, la Tapette 100\u202f% et l’Insecticide extra-fort sont retirés, ceux de votre réserve ou posés dans le restaurant sont devenus des Pièges au fromage et des Tentations caramel (ceux posés durent 24 heures depuis la mise à jour)\u202f; revendus à la boutique, ils rapportent au plus leur prix en diamants × 2\u202f000 pièces (pour les articles en pièces, 10\u202f000 pièces comptent pour 1 diamant)',
  bar1026:
    'Récompenses du bar\u202f: Gobelets coûte 2 bons mystère par partie et le dernier palier donne 6 récompenses de niveau 8\u202f; Cocktail Mémoire coûte 3 et ses trois manches donnent une récompense de niveau 2, 4 et 6\u202f; Fléchettes et Mélange secret coûtent 3\u202f; Le dernier bonbon donne une récompense de niveau 1 à la table débutant et de niveau 3 à la table expert\u202f; les récompenses de niveau 4 et plus donnent des ingrédients de niveau plus bas',
  darts1025:
    'Fléchettes\u202f: la main tremble un peu à chaque lancer, la fléchette se plante légèrement à côté du viseur et un lancer parfaitement minuté ne touche pas toujours le centre\u202f; la tolérance au délai réseau passe de 1,5 à 0,6 seconde',
  limits1025:
    'Trois nouvelles limites\u202f: 10 épreuves du temple par jour au maximum (réussies ou non)\u202f; pour prendre une place libre au classement des chefs, il faut avoir gagné un défi de la tour dans la semaine\u202f; goûter un plat signature donne au plus 25 points d’énergie',
  slot1024:
    'Nouveau lot à la machine à sous\u202f: le lot romarin de la machine à sous du bar (ingrédient de niveau 6, pas encore ouvert) devient le manuscrit autographe de Beethoven, Symphonie n° 9 (l’Ode à la joie), avec les mêmes chances',
  wiki1024:
    'Le wiki ne montre plus ce qui n’est pas encore ouvert dans le jeu\u202f: les recettes s’arrêtent au rang Délice (rang 7) et les ingrédients de niveau 6 sont masqués',
  spcoin1024:
    'Changement\u202f: le bonus «\u202fpièces des clients difficiles satisfaits +X\u202f%\u202f» des badges de rue et de l’assaisonnement secret ne s’applique plus qu’à ce que les clients difficiles paient pour les plats, plus au plat signature qu’ils mangent\u202f; les revenus du plat signature profitent toujours de votre bonus final de pièces',
  retire1023:
    'Les badges Sandy, Patrick et Bob l’éponge sont retirés\u202f: les livraisons ne croisent plus de clients mystères et cuisiner un plat signature ne vaut plus le pouce de Bob l’éponge\u202f; ceux que vous aviez et leurs bonus en cours ont été retirés',
  fridge1022:
    'Le frigo devient payant. Ce qui y entre (y compris le surplus quand le garde-manger est plein) paie des frais d’entrée de 5\u202f% du prix du marché, la décongélation coûte 10\u202f%, et le stockage coûte chaque jour 0,5\u202f% de la valeur du frigo, tout le frigo ×1,5 dès 21 sortes et ×2,25 dès 41. Vous pouvez maintenant mettre vous-même des aliments du garde-manger au frigo pour libérer des places. S’il vous manque des pièces, les frais deviennent une dette, et tant qu’elle n’est pas réglée vous ne pouvez ni décongeler ni mettre au frigo. Après 3 jours de dette, des aliments du frigo sont vendus pour la payer. La page du frigo indique le nombre de sortes et le coût quotidien approximatif',
  food1022:
    'Ingrédients. Le marché, la combinaison et la décomposition donnent un peu plus souvent les ingrédients qui manquent à tout le monde. Tous les ingrédients s’échangent maintenant à la Bourse, les ordinaires seulement entre joueurs (le système ne traite toujours que les rares). La souscription en gros choisit désormais parmi les ingrédients qui manquent le plus sur le serveur',
  feel1021:
    'Sensations\u202f: les boutons s’enfoncent sur iPhone sans le flash gris\u202f; les panneaux redescendent en se fermant, et on peut tirer la poignée du haut vers le bas pour les fermer\u202f; les notifications apparaissent et disparaissent en fondu\u202f; un bouton affiche une petite roue pendant le traitement au lieu de seulement griser\u202f; maintenez + ou − sur une quantité pour compter en continu',
  batch1020b:
    'Petits correctifs\u202f: quand un serveur désactive les ustensiles, la récupération d’endurance, les défenseurs du classement et la chance des livreurs amis suivent tout de suite le nouveau réglage\u202f; la tour des chefs se charge en une fois et s’ouvre plus vite\u202f; après un achat au marché et la fermeture d’un panneau, le focus revient sur le bouton utilisé\u202f; les barres d’onglets et leur contenu correspondent pour les lecteurs d’écran',
  batch1020:
    'Une série de petits correctifs\u202f: le retour de pouces en un clic explique les échecs, ne réessaie plus les anciens amis et s’arrête tout de suite si votre renommée est négative\u202f; les résultats du pronostic du marché apparaissent dans l’activité du restaurant avec les récompenses obtenues\u202f; tirer des missiles sur le gardien propose des boutons rapides 5, 10, 20 et 50\u202f; un restaurant racheté voit dans son historique de revenus et la fenêtre des pièces la part versée au propriétaire\u202f; les listes de valorisation, de ventes et d’investisseurs des rachats affichent la porte des restaurants\u202f; les restaurants à compte lié que vous possédez indiquent qu’ils ne peuvent pas être soignés et «\u202fTout soigner\u202f» les ignore\u202f; les règles de rachat, le prix du plat signature d’hier et la provenance des objets d’expertise suivent les réglages du serveur\u202f; le wiki indique que l’expertise donne un plat au hasard de la tranche de niveaux\u202f; le pack de départ prévient quand l’entrepôt est trop plein au lieu de dépasser la limite',
  email1019:
    'Nouveau. Vous pouvez changer d’e-mail. Si vous l’avez mal saisi à l’inscription et n’avez jamais reçu l’e-mail de vérification, appuyez sur «\u202fChanger d’e-mail\u202f» dans la ligne E-mail de Mon compte, saisissez la nouvelle adresse et votre mot de passe, et l’e-mail de vérification part vers la nouvelle adresse. Une adresse vérifiée ne peut plus être modifiée',
  review1019:
    'Corrections. Les restaurants avec le badge Plancton n’attirent plus de clients difficiles par temps de brume, de brouillard, etc. Les œuvres d’art qui augmentent seulement la capacité salle comble ou la capacité clients difficiles apparaissent désormais dans les bonus actifs de l’accueil. Le restaurant de M. Krabs ne gagne plus de succès et ne prend plus de premières du serveur (ceux qu’il avait ont été retirés). Appuyer sur «\u202fManger\u202f» juste après l’heure du repas indique maintenant que le repas est passé. La carte de rachat d’un autre restaurant explique pourquoi vous ne pouvez pas acheter sa mise en vente',
  meal1019:
    'Nouveau\u202f: l’énergie des repas. Chaque jour, le déjeuner (12 h–14 h) donne 20 d’énergie et le dîner (18 h–20 h) en donne 30. Touche «\u202fManger\u202f» dans les tâches du jour sur l’accueil\u202f; ça peut dépasser le maximum, et un repas manqué n’est pas rattrapé',
  wage1019:
    'Correctif\u202f: les salaires des cartes de métier (11 sortes, dont ceux du grossiste du marché et du conseiller bancaire) ne s’ouvraient pas dans la réserve\u202f; ils s’ouvrent maintenant. La récompense hebdo Tueur de cafards de minuit et le classement des cafards écrasés ne comptent plus que les cafards écrasés chez de vrais amis, ni chez toi ni chez M. Krabs (les 30 derniers jours ont été recomptés à partir du journal)',
  frames1019:
    'Paliers de points de succès\u202f: 500, 1\u202f500, 3\u202f000, 5\u202f000, 8\u202f000 et 12\u202f000 points débloquent des cadres d’avatar en bois, bronze, argent, or, jade et arc-en-ciel. Mets-en un dans Tenue et titres et il apparaît sur ton avatar dans les listes d’amis, les classements et le forum. 12\u202f000 points donnent aussi le titre Maître des succès, et tous les succès qui rapportent des points donnent Modèle de la ville. Nouvelle catégorie Éditions passées (sans points)\u202f: Membre fondateur (boutique ouverte avant le 31/10/2026) et Témoin de la refonte des économiseurs (courrier de compensation récupéré)',
  hidden1019:
    '75 nouveaux succès\u202f: 57 succès cachés (masqués tant qu’ils ne sont pas obtenus, dans Succès → Catégories → Cachés), quatre nouvelles lignes, Unanimité (clients exigeants satisfaits), Salle comble (toutes les tables occupées), Pris la main dans le sac (pris à fouiller un placard) et Champion du bar de la semaine, et Habitué du bar gagne un palier pour avoir gagné aux dix jeux. Les historiques encore conservés ont été rattrapés',
  achieve1019:
    'Nouveau\u202f: les succès. 410 succès en dix catégories (restaurant, quotidien, recettes, plats spéciaux, amis, bar, tour, temple, finance, ville) rapportent des points de succès, et certains aussi des trophées et des titres permanents. Suivez votre progression dans Moi → Succès et exposez vos trophées dans une vitrine que vos amis peuvent voir. Les classements ont un nouveau tableau Succès (points, nouveaux cette semaine). La progression depuis l’ouverture du serveur a été rattrapée',
  oilsaver1019:
    'Refonte des économiseurs d’huile\u202f: les dix anciens économiseurs deviennent deux gammes, les économiseurs (réduction fixe par table) et les vannes (réduction en pourcentage), chacune en initial, intermédiaire et avancé (24 heures, 10 000 / 30 000 / 80 000 pièces en boutique) et en supérieur au marché noir (36 heures, 12 / 24 diamants)\u202f; les pièces Krab s’échangent contre le niveau supérieur (1 pour l’économiseur supérieur, 2 pour la vanne supérieure). Les économiseurs installés ont été remplacés par une Vanne à pièces du marchand d’huile (consommation totale d’huile -90\u202f% pendant 24 heures), les économiseurs moyens et spéciaux en réserve sont devenus des économiseurs intermédiaires, et chaque restaurant a reçu un courrier avec une Vanne à pièces du marchand d’huile en plus',
  champion1019:
    'Récompenses du classement des plats signature d’hier revues\u202f: au lieu d’une Formule secrète du Krabby Patty pour le 1er seulement, le 1er reçoit maintenant 2 Sceaux Délice et les 2e à 4e 1 chacun (chaque jour à 9 h)\u202f; les places sont celles du classement «\u202fValeur hier\u202f» des plats signature, les ex æquo partageant la même place',
  tower1018:
    'Récompenses du classement hebdomadaire de la Tour des chefs revues\u202f: 1er 25 diamants, 4 recettes mystère, le titre Dieu des chefs et 50 de renommée\u202f; 2e 20 diamants, 3 recettes, Saint des chefs et 40 de renommée\u202f; 3e 15 diamants, 2 recettes, Roi des chefs et 30 de renommée\u202f; 4e–8e 12 diamants, 1 recette et 10 de renommée\u202f; 9e–15e 5 diamants et 5 de renommée\u202f; plus de bons d’ingrédient mystère au hasard. Le classement de la semaine dernière (semaine du 12 octobre) est versé avec les nouvelles récompenses',
  foodcut1018:
    'Deux ingrédients utilisés par aucun plat sont supprimés\u202f: la noix et le poisson blanc du lac Tai (la noix des recettes, ce sont les «\u202fcerneaux de noix\u202f», non concernés)\u202f; les noix déjà dans votre garde-manger ou frigo deviennent autant de poitrine de porc, et le poisson blanc autant d’anis étoilé',
  premium1017:
    'Le marché premium rouvre\u202f: il propose 3 ingrédients de niveau 4 à 6 h, 12 h et 18 h, réservé aux restaurants qui détiennent une médaille du fonds B ou plus, 9 de chaque au maximum par réassort\u202f; le prix est 1,8 fois le prix du marché (au lieu de 2), soit 10\u202f% de remise pour les investisseurs, et la météo l’influence toujours\u202f; les descriptions des médailles B et A le mentionnent désormais',
  wikimc1017:
    'Les données du jeu ont maintenant les «\u202fPlats signature\u202f»\u202f: les 250 plats indiquent niveau, voie, valeur nutritive, multiplicateur de vente et ingrédients, ainsi que les météos où ils sont de saison, l’origine des fragments (objets d’expertise, échange d’éclats, boutique de saison, leçons) et le bonus de voie\u202f; la liste se filtre par voie et indique les météos de saison de cette voie\u202f; «\u202fPlats signature qui l’utilisent\u202f» sur les ingrédients mène à leur fiche\u202f; l’API ouverte a aussi les plats signature',
  art1017:
    'Nouvel équipement, les œuvres d’art\u202f: sous les équipements de l’accueil, deux nouvelles places, la scène musicale et le paravent (ouvertes à 1 étoile). Installez une musique ou un tableau pour 24 heures afin d’attirer plus de clients, d’attirer les clients exigeants, ou d’en accueillir plus quand la salle est pleine. La boutique a une nouvelle catégorie Œuvres d’art, et quelques chefs-d’œuvre ne se vendent qu’au marché noir. Le dernier lot du kuji (normal et de luxe) donne désormais le Disque d’or de Voyager, qui va sur l’une ou l’autre place, à la place du Krabby Patty et de la Boussole céleste',
  streets1017:
    'Rééquilibrage des rues\u202f: les 29 rues (sauf la Rue des débutants) ne modifient plus la fréquentation ni le taux de clients difficiles, et donnent à la place des pièces par table, des pièces des clients difficiles satisfaits, etc.\u202f; la force des rues est harmonisée, aucune rue ne réduit les pièces ou l’EXP finales de plus de 10\u202f%, et le bonus d’ingrédients mystères en exploration passe de +2\u202f% à +1\u202f%. La base par étoile de la fréquentation et des clients difficiles devient 0,25 + 0,07 × étoiles et 0,12 + 0,03 × étoiles\u202f: presque pareil à 2 étoiles, et elle monte plus vite aux étoiles supérieures',
  predict1017:
    'Questions de prédiction du marché\u202f: la place de la Rue des débutants ne compte plus pour savoir si le rayon du jour aura des ingrédients rares d’un niveau donné (elle propose toujours un ingrédient de niveau 2 dont la Rue des débutants a besoin, ce qui décidait la plupart des questions de niveau 2), et les probabilités de départ sont estimées sans elle\u202f; les questions déjà publiées sont jugées comme avant\u202f; cette place porte désormais l’étiquette «\u202fDébutants\u202f» au Marché du jour',
  acquire1016:
    'Refonte des rachats\u202f: le système ne verse plus de dividendes\u202f; un restaurant racheté verse désormais 3,5\u202f% de chaque règlement à son propriétaire (4,9\u202f% après que celui-ci s’en est occupé dans la journée), et les restaurants rachetés ne reçoivent plus d’ingrédients gratuits\u202f; c’est désormais le propriétaire qui s’en occupe, en payant 1\u202f% de la moyenne quotidienne du restaurant, après quoi ses règlements sont × 1,035 et il reçoit des colis de ravitaillement de niveau 2\u202f; sans soins pendant 14 jours, le restaurant est lâché automatiquement\u202f; le rachat de force ne vise que les restaurants sans propriétaire\u202f: le restaurant reçoit 50\u202f%, tandis que 40\u202f% de frais de conseil et 10\u202f% de taxe sont détruits, et un restaurant qui a un propriétaire ne change de mains que par une mise en vente\u202f; le rachat de soi se fait à la valorisation de base et le propriétaire reçoit 60\u202f%\u202f; la valorisation passe à 3,5 fois la moyenne quotidienne\u202f; pour racheter, il faut au moins 2 étoiles et un compte d’au moins 7 jours, 3 achats par jour au plus\u202f; la carte Conseiller en fusions ne réduit plus la taxe',
  tower1016:
    'Butin de la tour\u202f: chaque victoire dans la tour a 10\u202f% de chances de donner une pièce de l’équipement de l’ancien de l’étage (20\u202f% aux étages 1 à 3 auparavant, puis 12, 8 et 5\u202f% plus haut)\u202f; les récompenses aléatoires de la tour et des duels amicaux ne donnent plus d’ustensiles mais des pièces à la place, les autres objets gardent leurs chances',
  spar1016:
    'Limite des duels amicaux\u202f: seuls les 10 premiers duels amicaux de la journée donnent des récompenses et de la renommée (50 auparavant)\u202f; la renommée pour avoir battu plus fort que soi ne change pas, et une défaite en fait toujours perdre',
  equip1016:
    'Les ustensiles ne se vendent plus\u202f: les ustensiles et l’essence d’ustensile ne peuvent plus être vendus à la boutique\u202f; démontez les ustensiles en trop pour en tirer de l’essence et servez-vous-en pour les renforcer\u202f; les récompenses des duels amicaux ne contiennent plus d’ustensiles, les pièces et l’EXP ne changent pas',
  commission1016:
    'Commission de la ville\u202f: une Commission ouvre en ville, présidée par le Maire Grosse Marmite, avec Carlo, le taoïste Fan, Sœur du Potager, Gary et Frère 13, chacun responsable d’un domaine et donnant un point du jour\u202f; les changements de règles sont annoncés par des communiqués, sur sa page et dans les nouvelles\u202f; chaque jour à 0 h, Carlo inspecte l’hygiène des restaurants de 2 étoiles et plus et la note dans l’activité du restaurant, à titre indicatif, sans amende',
  smurf1016:
    'Mesures contre les comptes secondaires\u202f: l’Ichiban Kuji demande désormais un e-mail vérifié pour acheter des tickets et tirer, ainsi qu’un restaurant niveau 10 pour le tirage normal, et niveau 20 avec un compte d’au moins 3 jours pour le tirage de luxe\u202f; le Pack de départ et les codes demandent un e-mail vérifié\u202f; le nombre de comptes créés depuis un même réseau ou un même appareil est limité',
  predict1016:
    'Prédictions et activité\u202f: la question quotidienne «\u202fLes pièces gagnées aujourd’hui par tout le serveur dépasseront-elles celles d’hier\u202f?\u202f» est remplacée par «\u202fL’Arbre à vœux portera-t-il un objet donné à 20 h aujourd’hui\u202f?\u202f» (l’objet est tiré parmi les lots de l’Arbre à vœux), et les questions sur les pièces encore ouvertes sont annulées et remboursées\u202f; nouvelles tâches d’activité\u202f: faire un vœu à l’Arbre à vœux et changer la météo avec un objet, 5 points chacune\u202f; l’accueil affiche de nouveau jusqu’à 3 lignes de nouvelles de la ville',
  perf1016:
    'Performances\u202f: le jeu s’ouvre plus vite la première fois (le fichier principal est presque un quart plus léger, et le journal des mises à jour ne se charge plus qu’à l’ouverture de sa page), l’accueil et la page À emporter ne se rafraîchissent plus à intervalles réguliers quand l’application est en arrière-plan, et le classement Puissance ne fait plus attendre plusieurs secondes à la première ouverture\u202f; la «\u202fréussite des épreuves\u202f», qui n’a jamais eu d’effet, est retirée des descriptions de la météo',
  weather1016:
    'Effets de la météo sur le service ajustés\u202f: la fréquentation et le taux de clients difficiles de la météo s’appliquent désormais après le calcul de ceux de votre restaurant (y compris la part réduite au-delà des plafonds), les bonus du beau temps ne sont donc plus rognés et les restaurants à beaucoup d’étoiles n’absorbent plus le mauvais temps grâce à leur fréquentation en surplus\u202f; la plupart des mauvais temps sont adoucis, par ex. Smog fréquentation -80\u202f% → -35\u202f% et pièces et EXP +100\u202f% → +60\u202f%, Grand vent clients difficiles -70\u202f% → -25\u202f%, Pluie acide fréquentation -90\u202f% → -40\u202f%, et EXP par table sous la pluie et la neige environ divisée par deux\u202f; Ensoleillé, Couvert, Nuageux, Tempête de sable, Nuit claire et Nuit nuageuse donnent +5 à +10\u202f% de pièces finales en plus, et le bonus de clients difficiles de Brouillard, Nuit brumeuse et Nuit étoilée est divisé par deux\u202f; la fréquence de chaque météo ne change pas',
  fair1015:
    'La bourse, les contrats à terme et la souscription en gros utilisent désormais le juste prix (au-dessus du prix du marché aux niveaux 3 à 5, proche du coût de fabrication)\u202f: les prix unitaires des contrats à terme et les mises à prix en gros augmentent, et les prix de référence des ingrédients de niveau 2 à 5 repartent des échanges de la veille ou du nouveau juste prix\u202f; le Marché des promos est tarifé par niveau\u202f: niveau 3 à 2\u202f499, niveau 4 à 5\u202f999, niveau 5 à 14\u202f999 (les ingrédients populaires de niveau 2 restent à 2\u202f999)\u202f; le prix de base de la grenouille des neiges et du foie gras baisse à 4\u202f200, celui de la farine complète monte à 9\u202f300 (l’EXP de cuisine des plats qui les utilisent change aussi)\u202f; les fiches d’ingrédient du wiki affichent le prix du marché et le juste prix',
  prices1015:
    'Prix des objets revus (1 diamant vaut désormais 10\u202f000 pièces)\u202f: la plupart des prix du marché noir changent, fragments, licences d’enseignant moyennes et hautes, économiseurs d’huile et cristaux mystères baissent, cartes d’extension, cartes d’exploration, pierres de renforcement et cartes de réattribution augmentent\u202f; cartes d’assurance et boussoles célestes arrivent au marché noir, conques violettes, fragments niv. 6 et licences d’enseignant débutant le quittent\u202f; à la boutique, nouveaux prix pour cartes d’agrandissement, affiches, trophées, économiseurs, missiles et cartes d’exploration, petites cartes d’endurance et boussoles célestes en vente, cartes d’endurance seulement au marché noir\u202f; petites cartes d’endurance et cartes d’endurance limitées à 1 par jour, pierres de renforcement à 2 par semaine\u202f; tickets d’Ichiban Kuji à 45\u202f000 et tickets de luxe à 320\u202f000, lots revus\u202f; ouvrir les commandes à emporter coûte 5,88 millions de pièces et 100 diamants\u202f; une carte d’exploration coûte 5 d’endurance\u202f; salaire du guide d’exploration 1 carte, du conseiller en placements 3 colis niv. 5, et bonus d’ingrédient mystère du guide +1\u202f%',
  float1015:
    'Fluctuations ajustées\u202f: la variation aléatoire de la fréquentation à chaque tour est divisée par deux (par ex. 2 étoiles ±25\u202f% → ±12,5\u202f%, 7 étoiles ±50\u202f% → ±25\u202f%)\u202f; celle du taux de clients difficiles passe à ±2,5\u202f% par étoile (au lieu de ±1,5\u202f%), toujours symétrique et sans changement en moyenne',
  income1015:
    'Revenus du restaurant revus\u202f: les clients ordinaires paient eux aussi un plat de votre rue (un plat appris rapporte 4,8\u202f% de son prix, 64 au plus par table\u202f; un plat non appris rapporte 10 + le niveau d’étoiles)\u202f; un client difficile satisfait paie 4 fois ce que paie un client ordinaire pour le même plat\u202f; plus vous apprenez de plats de votre rue, plus le taux de clients difficiles monte (jusqu’à +15\u202f% quand tout est appris, toujours soumis au plafond)\u202f; les pièces et l’EXP finales de chaque médaille de rue sont rééquilibrées pour les nouvelles règles, et la fréquentation ou l’EXP par table change sur 12 rues comme le Mexique, la France et le Sichuan, voir le bonus de rue sur la page de déménagement',
  streets1014:
    'Bonus des rues réajustés\u202f: les pièces et l’EXP finales de chaque médaille de rue sont rééquilibrées, y compris pour les restaurants déjà installés (pénalité de pièces plus faible rues Fusion I et II et rue du Guangdong\u202f; rue de Grèce EXP finale +85\u202f% → +80\u202f% et plus de bonus de pièces\u202f; rue du Shandong sans la fréquentation -20\u202f%, EXP par table +6 → +2\u202f; voir le bonus de rue sur la page de déménagement). La fréquentation au-delà de 70\u202f% ne compte plus que pour un tiers, celle apportée par les recettes apprises est divisée par deux, et la part au-delà de 120\u202f% se transforme toujours en EXP',
  fix1014c:
    'Petites corrections\u202f: la liste au comptant de la bourse se filtre par niveau (avec «\u202fEn vente\u202f» et «\u202fDemandés\u202f»)\u202f; les recettes de l’API ouverte ont leur description en chinois traditionnel\u202f; une fois qu’un lot de souscription en gros est figé, le tableau reste figé même si le serveur raccourcit la période',
  fix1014b:
    'Encore des petites corrections\u202f: les nouvelles de rachat affichent le nom actuel du restaurant racheté et ne renvoient plus vers un restaurant disparu\u202f; en modifiant une offre de souscription en gros, une note rappelle qu’une nouvelle offre (même en ajoutant seulement des unités) vous replace à la nouvelle heure\u202f; le code du gros pack de bienvenue ne sert qu’aux restaurants ouverts avant le pack, et les nouveaux restaurants ne peuvent pas l’utiliser sur les serveurs qui ne donnent pas le pack\u202f; les deux connexions vers le serveur de jeu sont préparées dès le chargement, la première action est un peu plus rapide',
  fix1014:
    'Petites corrections\u202f: les onglets se changent avec les flèches du clavier, le soulignement suit quand le texte d’un onglet change de largeur, et l’autre ligne de l’Ichiban Kuji est grisée pendant un tirage\u202f; les panneaux du bas ne mettent plus le focus sur un bouton à l’ouverture (Entrée ne valide plus d’office), et Tab reste dans le panneau\u202f; l’activité du jour, les quêtes, les événements, l’arbre à vœux et les infos du restaurant affichent un échec de chargement au lieu de charger sans fin\u202f; les quêtes d’invitation précisent que l’ami doit vérifier son e-mail\u202f; l’aide des contrats à terme reprend les chiffres de ce serveur\u202f; en ouvrant directement un ustensile dans le wiki, le retour mène à la liste des ustensiles\u202f; plus de lots de souscription en gros quand la bourse est fermée',
  shiling1014:
    'Refonte des points de saison\u202f: seules les parts mangées par les clients difficiles et par Carlo rapportent des points de saison, et non plus celles des clients ordinaires\u202f; un plat est de saison selon la météo du tour où il est mangé, et non plus à la cuisson\u202f; les points par part suivent le prix des ingrédients du plat, environ 1 point pour 1\u202f100 pièces d’ingrédients\u202f; au-delà de 500, les points de saison baissent de 1\u202f% par jour',
  mccut1013:
    'Nettoyage des plats signature\u202f: 27 plats signature retirés (10 plats vides sans ingrédients, et les 17 plats de la voie des bêtes qui demandaient des ingrédients niv. 6)\u202f; il en reste 250. Sans plats de la voie des bêtes, la météo spéciale (arc-en-ciel, ouragan, pluie acide, orage violent, grand gel) met désormais les six voies de saison',
  cuts41013:
    'Retraits, 4e vague\u202f: les packs du classement des chefs sont réduits (1re place\u202f: 100 de renommée, 1 bon d’ingrédient mystère au hasard, 8 recettes mystère, 50 diamants\u202f; moins pour les places suivantes)\u202f; les plaques étoilées ne donnent plus d’EXP par table, EXP finale +3\u202f% à +30\u202f% (1 à 7 étoiles)\u202f; «\u202fGrande ouverture\u202f» passe à EXP et pièces +50\u202f%, fréquentation +25\u202f%\u202f; «\u202fCoupe du Dieu des étoiles\u202f» EXP +10\u202f%\u202f; «\u202fFaveur du Dieu des étoiles\u202f» passe à pièces et EXP +75\u202f%\u202f; l’Aiguille du désir, le Manuel de l’explorateur et la Poupée vaudou sont retirés. Les plaques déjà exposées et les honneurs déjà obtenus suivent les nouveaux effets',
  cuts31013:
    'Retraits, 3e vague\u202f: les plaques commémoratives 2023 et 2025 et «\u202fSuccès immédiat\u202f» disparaissent (les bonus de collection de plaques et d’honneurs ne sont plus renforcés)\u202f; «\u202fDescente du Dieu de la fortune\u202f» disparaît\u202f; les senbei, la Médaille Grand Amour, le nœud chinois, le trèfle à quatre feuilles et la carpe koï sont retirés, et la quête principale «\u202fAtteindre cinq étoiles\u202f» ne donne plus la médaille. Plusieurs honneurs sont affaiblis\u202f: la Main de Dieu ne garantit des ingrédients qu’à la première fouille du jour, EXP +1\u202f%, chance +5\u202f; Cœur brisé jusqu’à l’os EXP +3\u202f%, pièces +2\u202f%, chance +10\u202f; Pétards EXP +2\u202f%, chance +8\u202f; Lanterne EXP +1\u202f%, chance +6\u202f; Bonheur EXP +1\u202f%, chance +4\u202f; Roi des j’aime EXP +1\u202f%\u202f; Salué par tous EXP +2\u202f%\u202f; Étoile de la livraison EXP des livraisons +10\u202f%\u202f; les titres du classement des chefs donnent +3\u202f%, +2\u202f% et +1\u202f% de pièces et d’EXP finales. Les honneurs déjà obtenus suivent les nouveaux effets',
  cuts21013:
    'Moins d’objets, deuxième vague\u202f: les statues Apollon, Monument de la Renaissance africaine, Vulgaire et Le Penseur, la Clé de lumière stellaire, le Border collie, le Livre du Dieu des étoiles, la Lampe à pétrole, le Cœur qui bat la chamade et l’Attrape-rêves disparaissent\u202f; avec eux disparaissent la conversion des pièces en EXP, le renvoi manuel de M. Krab en colère, la seconde expertise, les Sceaux de jade du Dieu de la cuisine sur les coups critiques du gardien et les livraisons ratées changées en réussites\u202f; la boutique de renommée propose désormais une des statues restantes chaque semaine',
  yard1013:
    'Le potager disparaît\u202f: cultures, vols de récoltes, panier, formules et engrais sont supprimés, ainsi que le Rouleau de l’étoile et de la lune\u202f; les étapes du potager dans les quêtes principales et secondaires disparaissent aussi, et le chapitre 5 de la quête principale s’appelle désormais «\u202fUstensiles et Tour des chefs\u202f»',
  cuts1013:
    'Moins d’objets\u202f: les tableaux, la Lampe magique et le Vœu du village, le Collier d’amour et Mission accomplie (portions doubles en livraison) disparaissent\u202f; le Marché premium demande désormais une médaille du fonds de rang B ou plus\u202f; les récompenses d’activité ne sont plus doublées\u202f; les quêtes secondaires perdent les étapes «\u202fPosséder 7 tableaux\u202f» et «\u202fFaire un vœu avec la Lampe magique\u202f»',
  special1013:
    'Nouvelle vente des plats spéciaux\u202f: les clients difficiles satisfaits en prennent toujours 2 portions à plein prix, ceux qui ne sont pas satisfaits ou qui partent n’en prennent pas\u202f; les clients ordinaires n’en commandent plus qu’à environ la moitié de leurs tables à chaque tour (1 portion à moitié prix), au lieu de toutes. La page des plats spéciaux indique les chiffres de votre serveur',
  fix1013b:
    'Encore quelques corrections\u202f: la boutique indique combien il vous manque au lieu de «\u202fil reste 0\u202f»\u202f; les souvenirs de l’entrepôt s’ouvrent pour afficher leur description complète\u202f; dans la liste des recettes, les plats au niveau max ont leur image d’ingrédient, la pagination est dans la carte et le détail aligne les ingrédients de chaque rang\u202f; les durées d’épargne indiquent combien de paquets on reçoit par montant déposé\u202f; une proposition refusée en Souscription en gros garde ce que vous avez saisi, et le panneau se rafraîchit toutes les 30 secondes tant qu’il est ouvert\u202f; les lecteurs d’écran nomment la case de quantité et ne lisent plus comme des interrupteurs les cases qui ouvrent un panneau',
  home1013:
    'Accueil plus compact\u202f: les pièces, l’EXP et l’huile du dernier tour sont dans une seule carte avec les tables, «\u202fMon restaurant\u202f» tient en trois petites cases, les nouvelles du village affichent 2 lignes et les équipements tiennent à quatre par ligne, les emplacements verrouillés résumés en une ligne. Touchez les pièces, l’énergie, les diamants, la renommée ou l’anneau de niveau sous la bannière pour savoir ce que c’est, comment l’obtenir et à quoi ça sert',
  fix1013:
    'Petites corrections\u202f: un restaurant fermé rouvre dès qu’il reçoit de l’huile, quelle qu’en soit la source\u202f; le marché débite exactement le prix unitaire affiché, garde le panneau ouvert si l’achat échoue et réactive les offres spéciales à la fin du délai\u202f; les commandes de contrats à terme sont limitées à ce que vos pièces couvrent en acompte\u202f; l’épargne et le fonds de développement passent à «\u202fRécupérer\u202f» à l’échéance même page ouverte\u202f; l’arbre à vœux affiche les derniers tours par date de tirage\u202f; les bons de la machine à sous ont des séparateurs de milliers',
  handle1013:
    'Traitement au garde-manger\u202f: dans vos traitements gratuits du jour, un traitement ne coûte pas d’énergie quelle que soit la quantité\u202f; ensuite, chaque ingrédient obtenu en combinant ou décomposé coûte 1 énergie (avant, 1 par traitement). Le panneau se ferme après le traitement pour que le résultat reste visible',
  picky1012:
    'Clients difficiles rééquilibrés\u202f: ils commandent un plat de votre rue 9 fois sur 10 et d’une autre rue 1 fois sur 10, sans plus dépendre des étoiles\u202f; avec au moins 30 plats de votre rue appris, ils choisissent toujours un plat que vous savez cuisiner, sinon ils peuvent commander un plat non appris et partir, et la table ne rapporte rien\u202f; si votre qualité est insuffisante, ils sont mécontents mais paient la moitié du prix du plat (avant, un petit montant de base)\u202f; le taux de clients difficiles monte de 2\u202f% par étoile (6\u202f% avant), et la part au-delà de 30\u202f% ne compte que pour un tiers',
  jobcard1012:
    'Refonte des cartes de métier\u202f: le Garçon hip-hop et le classement des pourboires disparaissent\u202f; les cartes viennent désormais du classement de saison (page météo\u202f: chaque dimanche à 23 h, les 3 premiers avec au moins 200 points de saison dans la semaine en tirent une chacun). Les cartes portent des noms de métiers, avec six nouvelles (Courtier de la Bourse, Trader en contrats à terme, Conseiller en placements, Conseiller en fusions, Vendeur du stand Kuji, Analyste des prédictions) qui baissent chacune des frais dans leur système\u202f; toutes donnent pièces et EXP finales +5\u202f%, et les salaires baissent nettement. Le quiz du maire devient un pari sur la prochaine météo\u202f: bonne réponse récompensée, aucune pénalité sinon',
  shiling1012:
    'Saisons\u202f: chaque météo met deux voies de plats signature de saison, et une fournée cuisinée de saison est de saison (dès 1 étoile). Les clients qui mangent vos plats de saison vous rapportent des points de saison à dépenser à la boutique de saison de la page météo (fragments, boussoles célestes, bâtonnets du temps)\u202f; choisir le plat d’épreuve coûte maintenant des points de saison. Le Kraken et la boutique de tentacules disparaissent, la marmite du maire ne donne plus de graines et les récompenses aléatoires ne donnent plus d’engrais ni de formules arcanes. Vos graines valent 5 points de saison chacune, les tentacules 30',
  weather1012:
    "Refonte de la météo\u202f: elle change toutes les 4 heures et suit le temps actuel, et la page météo affiche la prévision du prochain changement et un petit guide. Le Marteau de Thor est remplacé par la boussole céleste (choisir un type\u202f; le maire en échange 1 par semaine, et on en trouve au dernier lot de l'Ichiban Kuji et à l'arbre à vœux) et les bâtonnets du temps (en tirer deux, en garder un\u202f; 1 par jour à la boutique). Les deux durent 1 heure, et personne ne peut rechanger la météo dans l'heure qui suit",
  season1012:
    "L'Assaisonnement peut maintenant recevoir des points, comme la Cuisine, la Découpe et la Maîtrise du feu\u202f; une carte de réinitialisation les rend aussi. Les anciens de la tour en mettent aussi dans l'Assaisonnement\u202f: chaque étage a été rééquilibré et n'est pas plus facile qu'avant",
  tables1012:
    "En montant de niveau, la nouvelle table s'installe toute seule\u202f: une Table A de l'entrepôt d'abord, sinon achetée au prix de la boutique. S'il manque des pièces ou si les étages sont pleins, rien n'est débité et le fil du restaurant explique pourquoi",
  tower1012:
    "Dans la tour, touchez un étage pour ouvrir le panneau de l'ancien\u202f; essais et défis s'y trouvent, les lignes n'ont plus de bouton de défi",
  mousetrap1012:
    "Les tapettes attrapent désormais les souris venues voler vos ingrédients avec la probabilité indiquée, comme pour les amis qui fouillent votre garde-manger (avant, votre chance était vérifiée d'abord, et plus elle était haute, moins la tapette servait). Les descriptions et le fil du restaurant le précisent",
  cupboard1012:
    "Le garde-manger devient une liste, un ingrédient par ligne\u202f: une petite image, le niveau après le nom, ce que la rue demande encore en dessous et la quantité à droite. Une barre de recherche filtre par nom, sur l'étagère comme dans le frigo",
  thumbs1012:
    "Tout rendre ne signale plus d'échec quand vous aviez mis un pouce à quelqu'un avant qu'il vous en mette un\u202f: c'est déjà compté comme rendu",
  account1012:
    "Connexion, compte, centre d'aide et bibliothèque repensés\u202f: la porte de la ville en tête des pages de connexion et d'inscription, chaque champ a son titre et sa propre ligne d'erreur, et l'œil affiche le mot de passe\u202f; chaque serveur est une carte avec votre restaurant\u202f; langue, apparence et mot de passe se changent dans des panneaux\u202f; les récompenses des codes ont des images et le code d'invitation est dans un cadre pointillé\u202f; le centre d'aide passe en tuiles et le guide se replie\u202f; le journal des mises à jour et la bibliothèque prennent un air de journal, les listes ont des images et les fiches d'objets, d'ingrédients, de recettes et de rues se lisent comme un petit carnet",
  social1012:
    "Guilde, Place, Forum, Amis et Courrier repensés\u202f: la Guilde et la Place ont une image d'en-tête, le maire, Frère 13 et Carmen ont un portrait dans une rangée qui montre avec qui vous avez parlé aujourd'hui\u202f; gagner une étoile et agrandir le bidon listent ce qui manque, renommer et déménager se font dans un panneau\u202f; répondez au maire en touchant un lieu, choisissez les quantités d'objets rares dans un panneau et les ingrédients mystère de Carmen dans une grille\u202f; un panneau pour choisir la spécialité et le certificat d'un cours\u202f; le journal de la ville ressemble à un vrai journal, annonces et marteau de Thor passent par des panneaux, les classements ont des médailles et des avatars\u202f; les sujets du forum sont des cartes, la réponse est en bas et modifier/supprimer sous «\u202f⋯\u202f»\u202f; les lignes d'amis indiquent repas gratis, cases du garde-manger et cafards, le restaurant d'un ami reprend votre en-tête avec une grille d'actions et des tables à toucher\u202f; les pièces jointes ont des icônes et chaque courrier s'ouvre dans un panneau",
  play1012:
    'Bar, Temple et Tour des chefs refaits\u202f: les trois ont une image d’en-tête avec vos bons, votre énergie ou votre puissance\u202f; l’accueil du bar est une grille des dix jeux avec les parties du jour et celles en cours, chaque jeu a sa page, les règles sont une courte liste sous Règles et les récompenses ont une image\u202f; au temple, expertiser, tirer, explorer et nourrir se règlent dans un panneau, et l’épreuve ouvre un panneau d’ingrédients depuis les cases principal et secondaire\u202f; la tour montre un étage par ligne, un étage s’ouvre avec son gardien et l’équipement de l’ancien, et les résultats des duels et les juges s’ouvrent en bas',
  trade1012:
    'Boutique, Bourse, Rachats, Ichiban Kuji, Prédictions, Livraison et Banque refaits\u202f: la boutique montre un objet par ligne avec des filtres et un bouton prix qui ouvre un panneau d’achat\u202f; la bourse montre un ingrédient par ligne avec sa variation, et le carnet d’ordres et l’ordre s’ouvrent en bas, comme les contrats à terme et les enchères en gros\u202f; les classements de rachat ouvrent un panneau avec la part du propriétaire et la taxe\u202f; le kuji montre une ligne par lot et les résultats dans un panneau\u202f; chaque prédiction a sa page avec un graphique et votre gain dans les deux cas\u202f; la livraison coche chaque condition et le livreur se choisit dans un panneau\u202f; le garçon hip-hop est replié sur une ligne au départ',
  pages1011:
    'Pages du restaurant refaites\u202f: les 12 avatars ont maintenant une image, avatars et portes sont des vignettes illustrées\u202f; la page des ustensiles montre un emplacement par ligne avec le nom complet, les attributs sont des barres (violet foncé pour les points, violet clair pour les ustensiles), et changer d’ustensile ou répartir les points s’ouvre en bas\u202f; le détail d’un ustensile montre un anneau de réussite et les emplacements de gemmes\u202f; «\u202fAujourd’hui\u202f» dans les quêtes est une barre d’activité avec ses paliers, et les quêtes sont des lignes dans une carte\u202f; les recettes ont trois sortes de boutons selon qu’on peut les apprendre, les spécialités 12 par page\u202f; le stockage est une grille avec un panneau par objet\u202f; toucher une table ouvre un panneau, et les revenus ont un petit graphique des 30 derniers tours',
  market1011:
    'Le placard devient une grille de sac\u202f: grandes icônes, quantité dans le coin, ingrédients de niveau 2 et plus et universels teintés\u202f; touchez une case pour un panneau avec la quantité possédée, l’objectif de la rue et les actions décomposer, combiner, échanger ou verrouiller\u202f; le frigo affiche une ligne par ingrédient. Le marché montre une ligne par ingrédient avec son niveau après le nom et un bouton prix qui ouvre un panneau d’achat\u202f: choix rapides 10 / 100 / max, total et solde, et un avertissement si les pièces manquent',
  home1011b:
    'Nouvelle mise en page de l’accueil\u202f: devanture plus grande, avec un panneau «\u202fFermé\u202f» quand l’huile est épuisée\u202f; le niveau s’affiche dans un anneau d’expérience\u202f; l’huile et le plein sont dans une carte d’état en haut, avec le plein en un geste quand le restaurant est fermé\u202f; le dernier tour montre trois grands chiffres\u202f; pointage, quête principale, activité du jour et conseils débutant deviennent de grandes tuiles 2×2, le pointage en violet tant qu’il n’est pas fait\u202f; recettes, plat signature et patrimoine sont regroupés sous «\u202fMon restaurant\u202f»\u202f; les pages principales ont des titres plus grands',
  kitchen1011:
    'Chaque ingrédient a maintenant une petite icône selon son type (viande, poisson, légumes, fruits…), visible dans le placard, le frigo, le marché et le détail des recettes. Le placard est une grille de quatre colonnes avec une carte pour l’ingrédient choisi\u202f; le marché, l’entrepôt et les plats signature règlent les quantités avec − et +, et vendre, jeter ou vider demande d’abord confirmation dans un panneau en bas. Le détail des recettes montre une ligne par niveau, avec les ingrédients manquants en rouge et les niveaux appris cochés\u202f; les pages affichent des blocs gris pendant le chargement et un conseil avec un lien quand elles sont vides',
  rest1011:
    'L’accueil montre maintenant la devanture de votre restaurant, avec la porte choisie dans Apparence\u202f; pièces, diamants, énergie et autres ont des icônes en couleur, et les équipements et emplacements d’ustensiles aussi. Les confirmations s’ouvrent par le bas, avec un bouton rouge pour démonter ou vendre\u202f; les quantités se règlent avec − et +\u202f; la liste des quêtes est plus compacte, avec une barre violette à côté de celles à récupérer\u202f; les préréglages et le traitement en lot des ustensiles s’ouvrent dans un panneau en bas\u202f; les pages affichent des blocs gris pendant le chargement',
  ia1011:
    'Le pointage et l’activité du jour deviennent l’onglet «\u202fAujourd’hui\u202f» des quêtes\u202f; plats signature et progression des recettes sont des onglets de Recettes\u202f; les gemmes, un onglet des Ustensiles\u202f; le fonds et l’épargne de Gary passent à la nouvelle «\u202fBanque\u202f» en ville\u202f; codes débutant et invitations sont sur la page Codes. Les onglets sont gardés dans l’adresse\u202f: on peut les partager et Retour garde votre place\u202f; les sous-classements sont un menu déroulant\u202f; la Promo du jour s’appelle désormais Promos limitées',
  shell1011:
    '«\u202fPlus\u202f» devient «\u202fVille\u202f», avec les lieux classés en Commerce, Loisirs et Public. Touchez votre avatar en haut à droite pour «\u202fMoi\u202f»\u202f: infos, tenue, ustensiles, entrepôt, codes, réglages et centre d’aide. Les titres sont dans la barre du haut et le bouton retour remonte d’un niveau',
  theme1011:
    'Nouvelles couleurs améthyste, avec des boutons, des champs et des onglets redessinés. Le mode sombre arrive\u202f: choisissez Comme le système, Clair ou Sombre dans Apparence, sous Mon compte',
  wishtree1011:
    "La place a un nouvel Arbre à vœux\u202f: tirage chaque jour à 20\u202fh, et l'arbre donne un nouvel objet au même moment. À partir du niveau 10, chaque restaurant peut faire 1 vœu gratuit par tour\u202f; au tirage, un restaurant qui a fait un vœu remporte l'objet et le titre «\u202fVœu exaucé\u202f» pendant 3 jours (envoyés par courrier). Les autres reçoivent une récompense aléatoire",
  ui1011:
    "Les entrées d'activité sur ce que vos amis vous ont fait (repas non payé, cafards, échanges d'ingrédients, etc.) mènent maintenant directement à leur restaurant, et les échanges précisent quel ingrédient de quel niveau a été échangé contre lequel. La liste du jour sur l'accueil gagne une ligne Bourse dès que vous remplissez ses conditions, avec la souscription en gros en cours et la quantité déjà demandée. La souscription en gros passe à l'aveugle pendant la dernière heure\u202f: prix prévu, limite et quantités demandées sont figés à ce moment-là, et les résultats sont révélés à la clôture",
  bulk1010:
    "La bourse a un nouvel onglet Souscription en gros\u202f: chaque jour à 20\u202fh, un lot d'un ingrédient (niveaux 1 à 5) est proposé. Proposez un prix unitaire et une quantité\u202f; le prix de la dernière unité retenue est le prix unique payé par tous, et le surplus gelé est rendu. Chaque joueur peut prendre jusqu'à 25\u202f%\u202f; s'il y a moins de 30\u202f% de demandes au total, le lot échoue et tout est remboursé. Le lot clôture à un moment aléatoire dans les 5 dernières minutes, et il faut attendre 5 secondes entre deux offres. Ceux qui ratent de peu reçoivent un ticket d'ingrédient aléatoire de niveau 2",
  wealth1010:
    "L'Association propose désormais des placements\u202f: placez des pièces 3, 7 ou 14 jours et récupérez tout le capital à l'échéance, plus un colis de ravitaillement du marché de niveau 3, 4 ou 5 par tranche de 1\u202f000\u202f000 pièces. À l'ouverture, le colis donne un ingrédient de son niveau qui manque à la rue où vous êtes. Jusqu'à 3 placements et 10\u202f000\u202f000 pièces au total, dès le niveau 20\u202f; un retrait anticipé rend 95\u202f%, sans colis",
  futures1010:
    'La bourse a un nouvel onglet Contrats à terme\u202f: commandez un ingrédient précis, payez un acompte de 30\u202f% pour fixer le prix, et il est livré automatiquement 3 jours plus tard, le solde étant prélevé à ce moment-là (ce qui ne rentre pas au garde-manger va sur votre compte de la bourse). Si vous ne pouvez pas payer le solde à l’échéance, ou si vous annulez avant, le contrat est en défaut et l’acompte n’est pas rendu. Chaque ingrédient a un quota quotidien pour tout le serveur, et chaque joueur peut commander jusqu’à 50 unités par jour au total',
  backlog1010:
    'Chaque bouton de récompense d’activité indique maintenant ce que donne ce palier. Quand quelqu’un finit de manger gratis et s’en va, un patron banni ne reçoit plus d’objet, et l’objet du patron n’est jamais un Bon mystère. Le classement des bons gagnés au Piment du Diable compte désormais le gain net (gain moins la mise), et la table des gains ne change plus en cours de partie. Quand quelqu’un répond à une réponse de l’auteur du sujet, le journal précise laquelle, et répondre à un message supprimé ne prévient plus son auteur. La page d’invitation affiche les niveaux de récompense de votre serveur. Les gardiens de la tour s’appellent désormais Veilleurs de la tour, pour ne plus les confondre avec le Gardien. Quelques textes, libellés pour lecteurs d’écran et l’emplacement des messages ont aussi été corrigés',
  fix1010:
    'Les souris choisissent désormais quoi voler selon la quantité\u202f: ce que vous avez en abondance est pris plus souvent, et les ingrédients rares dont vous n’avez que quelques unités sont rarement touchés. Dans Étages et tables, les tables d’une même rangée ont maintenant la même hauteur',
  rank1010:
    'Les classements ont désormais des tableaux de cette semaine et de la semaine dernière pour d’autres jeux du bar\u202f: Fléchettes (victoires), Le dernier bonbon (tables débutants et experts séparées), Mélange secret (moins d’essais en une partie et mélanges trouvés), Cocktail Mémoire (parcours complets), Piment du Diable (bons gagnés) et À prendre ou à laisser (gros lots). Sauf pour Cocktail Mémoire, le décompte commence avec cette mise à jour',
  ui1010:
    'En répartissant les points, chaque case s’arrête aux points restants, et un bouton Tout a été ajouté. Dans Étages et tables, chaque table indique le plat commandé ou la spécialité mangée\u202f; touchez une table pour voir le grade voulu, le vôtre et si le client était satisfait. Les cafards sont désormais signalés sur le lien Étages et tables de l’accueil et sur les boutons d’étage. Quand un client gratuit finit de manger et part, le propriétaire reçoit désormais un objet au hasard. Les noms des autres restaurants dans Nouvelles de la ville sont maintenant des liens. En visitant un restaurant, sa rue s’affiche, suivie des titres, de l’annonce, du rachat et des ustensiles. La page de la Guilde est plus compacte, les installations de l’accueil vont par trois, les titres sont alignés sur le texte voisin et les couleurs d’accent sont désormais le même orange foncé',
  feed1009:
    'L’accueil a une nouvelle carte «\u202fActivité du restaurant\u202f» qui montre qui est passé chez vous et ce qui s’y est passé, avec un point devant les nouveautés. L’activité inclut désormais aussi les clients gratuits qui partent après avoir mangé, les réponses à vos sujets du forum, le rachat ou la libération de votre restaurant, un restaurant que vous possédez qui se rachète, les souris qui volent des ingrédients, les achats de votre réapprovisionnement et les ingrédients jetés quand le frigo est plein\u202f; l’embauche comme livreur s’affiche aussi désormais. Le total de pouces levés reçus s’affiche en visitant un restaurant et sur la page d’infos du restaurant. L’accueil n’affiche que les annonces récentes. Les récompenses de quêtes ne se récupèrent plus depuis l’accueil\u202f: une icône cadeau sur le lien Quêtes signale les récompenses principales, hebdo ou secondaires à récupérer et vous y mène',
  ui1009:
    'Les messages d’action s’affichent désormais en petites pastilles en bas de l’écran au lieu de masquer le haut de la page, et les messages de réussite courts disparaissent plus vite. Sur la page des revenus, la section des bonus, repliée, est de nouveau en haut',
  titles1009:
    'Les badges de titre ont désormais le même style jaune sur votre accueil et chez les autres restaurants. Vous pouvez maintenant recevoir des titres par courrier ou code cadeau\u202f; les titres temporaires indiquent leur durée. Après réception, choisissez ceux à afficher sur la page Apparence',
  devil1009:
    "Piment du Diable\u202f: 20 parties par jour au maximum\u202f; les gains suivent désormais un tableau fixe. Avec une mise de 1 bon, tenir 1/2/3 verres rapporte 1/2/3 (comme avant)\u202f; une mise de 5 rapporte 7/9/12, 10 rapporte 14/18/25 et 20 rapporte 27/36/49, un peu moins qu'avant. Le tableau est affiché dans le jeu",
  fix1009:
    "Une série de petites corrections\u202f: la description du Collier d'amour ne mentionne plus le marché de luxe\u202f; l'étape de quête secondaire pour entrer dans le top 10 du classement des contributions d'un événement limité compte désormais toutes les places jusqu'à 10, pas seulement celles qui reçoivent une récompense\u202f; le Journal de la ville permet de revenir aux jours précédents et découpe mieux les paragraphes\u202f; la réussite estimée de l'Épreuve utilise la virgule décimale\u202f; ponctuation corrigée dans les e-mails d'inscription et de réinitialisation\u202f; les vœux retirés n'apparaissent plus avec un nom chinois dans les nouvelles",
  daily1009:
    "Nouveau\u202f: le Journal de la ville. Chaque matin, il raconte les grands moments de la veille (gros lots de l'Ichiban Kuji, acquisitions, passages d'étoile, résultats des prédictions, etc.). Il se trouve tout en haut des Nouvelles de la ville, avec un lien sur la page d'accueil\u202f; on peut remonter 7 jours et toucher le nom d'un restaurant pour le visiter. Il est rédigé par une IA à partir des nouvelles du jeu et ne parle que de ce qui s'est vraiment passé\u202f; tant que le journal d'un jour n'est pas prêt, ce sont les titres du jour qui s'affichent. Pour l'instant, le journal n'existe qu'en anglais",
  act1008:
    "Points d'activité\u202f: un tirage Ichiban Kuji rapporte 10 points\u202f; s'amuser au bar rapporte 2 points à chaque fois, jusqu'à 10 fois par jour\u202f; acheter au Marché compte 2 fois par jour\u202f; combiner ou décomposer des ingrédients rapporte 3 points à chaque fois, jusqu'à 5 fois\u202f; les défis de la Tour des chefs rapportent 5 points à chaque fois, jusqu'à 2 fois\u202f; nouvelle tâche «\u202fDonner ou recevoir un pouce levé\u202f», 2 points à chaque fois, jusqu'à 5 fois. Le maximum quotidien passe de 193 à 220 points. Les récompenses changent aussi\u202f: 50 points donnent en plus 10 Bons mystère, 100 points donnent en plus 10\u202f000 pièces, 120 points donnent un Ticket Ichiban Kuji et 4 diamants, 150 points donnent de l'EXP et 2 Petites cartes d'énergie, et 180 points donnent 1 Carte d'exploration",
  retire1008:
    'Un autre lot d’objets ne peut plus être obtenu (44 sortes, dont des animaux du zodiaque, des animaux de compagnie, des plantes, des bibelots et quelques plaques)\u202f: les 36 échanges du maire qui les donnaient disparaissent. Ceux que vous possédez déjà gardent leurs effets',
  text1008:
    "Nombres dans les quêtes et les règles\u202f: les quêtes secondaires sur la faveur du Kraken, le niveau des amis invités et les parts de Prédictions affichent désormais les valeurs réelles de ce serveur\u202f; si la limite de parts de ce serveur est inférieure à 200, l'étape «\u202fdétenir toutes les parts\u202f» se base sur cette limite et ne bloque plus les quêtes suivantes\u202f; plusieurs ingrédients mystères identiques d'une même bête gardienne n'apparaissent plus qu'en une seule actualité\u202f; les règles du duel culinaire précisent que le plat signature ne compte pas la valeur d'épreuve",
  punct1008:
    "Textes en français et en espagnol\u202f: l'espacement de la ponctuation est désormais uniforme. En français, une espace fine insécable avant les deux-points, les points-virgules, les points d'interrogation et d'exclamation et le signe de pourcentage, ainsi qu'à l'intérieur des guillemets\u202f; en espagnol, une espace insécable entre un nombre et le signe de pourcentage. Ces signes ne passent donc plus seuls à la ligne",
  robust1008:
    "Dividendes de rachat\u202f: si les revenus de la veille ne sont pas encore comptabilisés, ils le sont d'abord puis les dividendes sont versés, et un versement raté est retenté 10 minutes plus tard (avant, les dividendes de ce jour-là étaient perdus)\u202f; ouvrir une nouvelle page hors ligne affiche désormais un message au lieu de ne rien faire\u202f; l'horloge en haut se resynchronise avec le serveur quand vous revenez dans l'appli\u202f; après une déconnexion ou un changement de compte, les pastilles du courrier et des demandes d'ami n'affichent plus les chiffres du compte précédent",
  ux1008:
    "En changeant de page, on revient en haut (avant, on restait à la hauteur de la page précédente)\u202f; «\u202fN points à répartir\u202f» dans les Infos du restaurant mène directement au cadre des points de la page Ustensiles\u202f; en choisissant les ingrédients d'épreuve, ceux qui ne suffisent pas parce que le plat les utilise aussi sont grisés avec la raison, et une recherche sans résultat l'indique\u202f; la pénalité du Kraken sur la valeur d'épreuve s'applique à la valeur réellement prise en compte\u202f; sur mobile, le lien vers l'activité de la page des Quêtes passe au-dessus des onglets quand il ne tient pas\u202f; et quelques petites corrections sur des boutons et des textes pour lecteurs d'écran",
  zhComma1008:
    "Texte chinois\u202f: les virgules deviennent une virgule anglaise suivie d'une espace, pour gagner de la place",
  gemStrength1008:
    "Page des gemmes\u202f: le «\u202fÉnergie\u202f: N\u202f» à la fin de l'explication est désormais sur sa propre ligne, «\u202fMon énergie\u202f: N\u202f», pour préciser qu'il s'agit de votre énergie actuelle",
  perf1008:
    "Pages plus rapides à charger\u202f: moins d'allers-retours inutiles avec le serveur\u202f; l'accueil du restaurant, l'Historique des gains, les Infos du restaurant, les Recettes et les Rachats chargent leurs données en même temps\u202f; en rouvrant le jeu, les fichiers déjà téléchargés sont réutilisés",
  pages1008:
    "Page des revenus\u202f: l'historique est désormais en haut, avec les totaux du jour et une colonne Clients, et les bonus sont regroupés dans une section dépliable qui n'affiche que ceux différents de 0\u202f; les liens entre les Quêtes et la page d'activité n'occupent plus une ligne à part\u202f; la page Équipement affiche d'abord les emplacements et les boutons, et les explications sur la puissance et le reste passent dans «\u202fComment ces chiffres sont calculés\u202f»\u202f; le détail d'un ustensile n'affiche que les caractéristiques non nulles et indique clairement quand il ne peut pas recevoir de gemmes",
  fixes1008:
    "Les comptes à rebours et les temps restants suivent désormais l'heure du serveur, même si l'horloge de votre appareil est décalée\u202f; remplacer un équipement qui n'a pas expiré demande toujours confirmation\u202f; dans l'Historique des objets, les entrées qui ne sont pas d'aujourd'hui affichent la date\u202f; les grands nombres de progression des quêtes ont un séparateur de milliers\u202f; la quête principale «\u202fPlacer un équipement\u202f» mène désormais à l'accueil\u202f; Progression des recettes affiche «\u202fChargement\u202f» pendant le chargement",
  tasksSplit1008:
    "Le pointage et l'activité du jour ont désormais leur propre page, ouverte depuis les points d'activité de l'accueil\u202f; la page Quêtes a trois onglets (Principale, Hebdo, Secondaires), avec une icône cadeau sur ceux qui ont des récompenses à récupérer, et s'ouvre depuis le nouveau lien Quêtes sur la ligne de la quête principale de l'accueil\u202f; l'entrée Quêtes a été retirée du menu Plus",
  cookbookProgress1008:
    'La page Recettes propose une Vue d’ensemble de la progression\u202f: la progression totale par qualité, puis, rue par rue, le nombre de recettes de chaque qualité ou mieux, avec votre rue actuelle mise en évidence et les cases complètes en vert',
  gameTime1008:
    "Toutes les heures affichées dans le jeu (nouvelles de la ville, courrier, forum, fil des amis, historique de l'entrepôt, etc.) sont désormais à l'heure de Pékin, comme l'horloge en haut de la page, et non plus selon le fuseau horaire de votre appareil\u202f; le guide du débutant précise que l'énergie se recharge d'un point toutes les 10 minutes",
  renownTicket1008:
    'La boutique de renommée de la Tour des chefs propose désormais en permanence des Tickets d’ingrédient aléatoire niv. 4 (50 de renommée, 3 par semaine) et niv. 5 (80 de renommée, 2 par semaine)',
  economy1008:
    'Quelques façons de transformer des objets en pièces ont été ajustées\u202f: les objets qui ont un prix en diamants, quelle que soit leur provenance, se revendent à la boutique au plus 2\u202f000 pièces par diamant\u202f; les Pièces d’or du marché noir coûtent désormais 50 diamants\u202f; les tickets de l’Ichiban Kuji coûtent désormais 40\u202f000 pièces\u202f; les Bons d’ingrédient mystère, les Bons d’ingrédient mystère au hasard, toutes les cartes d’exploration et les Éclats de fragment ne se revendent plus à la boutique, ils servent seulement à être utilisés\u202f; la Bourse n’achète plus les ingrédients de niveau 7 (son stock existant reste en vente)',
  business1008:
    'Nouvelle ligne de quêtes secondaires «\u202fGestion\u202f» (dès le chapitre 2)\u202f: ajouter des tables, améliorer le bidon d’huile, installer des équipements, rester ouvert de nombreux tours en une journée et gagner de 100\u202f000 à 1\u202f000\u202f000 pièces de règlement en une journée. Les pièces et les tours comptent votre meilleure journée\u202f; une journée compte une fois totalisée, juste après minuit',
  sideB1008:
    'Encore des quêtes secondaires\u202f: nouvelles lignes Recettes mystères, Gardien, Veilleurs de la tour, Devinettes du Marché, Livraison experte, Acquisitions, Gemmes, Collection, Pointage et activité et Social\u202f; la ligne Ville ajoute le Fonds de développement, la question du Maire, le classement hebdomadaire du Garçon hip-hop, le Marteau de Thor et la Lampe magique\u202f; la ligne Temple ajoute la faveur du Kraken, les tentacules et 50 repas. Les séries de pointage comptent votre plus longue série, et les pointages des 30 derniers jours sont déjà pris en compte',
  sideA1008:
    'Plus de quêtes secondaires\u202f: la ligne du bar comprend l’essai de chaque nouveau jeu et 500 puis 2\u202f000 parties\u202f; deux nouvelles lignes, «\u202fChance au bar\u202f» (séries au chifoumi, Gobelets réussis, Piment du Diable, 100 parties de machine à sous…) et «\u202fAs du bar\u202f» (fléchettes, Cocktail Mémoire, Le dernier bonbon, Mélange secret, À prendre ou à laisser)\u202f; la Bourse ajoute les échanges avec le système, la vente à prix bradé au système, l’achat et la vente d’ingrédients rares et 500 échanges\u202f; les prédictions ajoutent la revente anticipée, la détention de 100 et 200 parts, et un gain ou une perte d’un certain montant en un règlement\u202f; l’Ichiban Kuji ajoute le tirage d’un Prix A et l’Ichiban Kuji de luxe\u202f; Chez soi partout ajoute des quêtes de la rue Chop Suey, la dernière étant «\u202fMal du pays\u202f»\u202f: apprendre tous ses plats',
  krab1008:
    'Les Pièces Krab ne peuvent plus être revendues à la boutique\u202f; elles servent uniquement à la machine à sous et à l’échange du maire',
  quest1008:
    'Changements de quêtes\u202f: passer à 1 étoile donne aussi 1 Recette mystère, 1 Sceau Délice, 1 Carte d’exploration et 9 [Niveau 1]•Éclat de fragment (de quoi échanger une spécialité de niveau 1)\u202f; la recette et la carte que donnaient les quêtes d’expertise et d’exploration sont déplacées ici\u202f; passer à 2 étoiles donne aussi 1 Pass à emporter\u202f; dès 1 étoile, les quêtes hebdomadaires comprennent «\u202fRécupérer les cartes d’exploration de la semaine\u202f», 3 cartes par semaine\u202f; la quête «\u202fréunir 4 plantes en pot\u202f» disparaît et le Dernier Prix de l’Ichiban Kuji donne en plus 1 Krabby Patty\u202f; le chapitre «\u202fLa voie des festins divins\u202f» et «\u202fMonter une recette en Mets divin\u202f», pas encore faisables, sont masqués pour l’instant',
  rank1008:
    'Les classements de séries au chifoumi, aux gobelets et à la roue des numéros prennent maintenant la meilleure série atteinte dans la semaine, avec un tableau pour cette semaine et un pour la semaine dernière\u202f: perdre une partie ne fait plus sortir du classement, et une série qui continue après le lundi compte toujours, dans la semaine où elle a atteint ce nombre\u202f; à égalité, le premier arrivé passe devant',
  odds1007:
    'Le cadeau de connexion quotidienne donne maintenant 1 à 5 diamants quand il en donne (1 à 3 avant)\u202f; sous le tableau des lots de la machine à sous, une note précise que les probabilités sont par case sans le lot garanti, et en combien de tirages tombe en moyenne un lot rare en le comptant',
  misc1007d:
    'Les cartes d’agrandissement petite, moyenne et grande sont maintenant à la boutique (30\u202f000, 120\u202f000 et 200\u202f000 pièces)\u202f; l’échange du maire affiche d’abord l’illimité, puis ce que vous pouvez échanger, ce qui vous manque et ce qui est épuisé, du moins cher au plus cher dans chaque groupe\u202f; quand un rachat est bloqué, le message précise que c’est parce que vous vous êtes connectés récemment depuis le même appareil ou réseau\u202f; après une mise à jour, une ancienne page qui n’arrive pas à en ouvrir une nouvelle se recharge une fois',
  retire1007:
    'Un lot d’objets inutilisés a été retiré\u202f: ils n’apparaissent plus dans la boutique, au marché noir, dans la promo du jour ni dans aucune récompense. Ceux que vous possédez déjà restent affichés et peuvent être utilisés ou vendus',
  cluster1007:
    'Changements du gardien du temple\u202f: le «\u202fMissile rapide\u202f» reprend son nom d’origine, «\u202fMissile à fragmentation\u202f», et inflige 3200 par tir au lieu de 2000 (un peu moins que 36 missiles standard)\u202f; le missile standard passe à 2400 pièces\u202f; la récompense pour avoir vaincu le gardien augmente avec ses PV, donc plus d’étoiles donnent plus d’ingrédients et plus de chances d’ingrédients mystère (parfois plusieurs). La valeur d’épreuve plafonne désormais à 30\u202f% au lieu de 50\u202f% (au-delà, elle compte pour 30\u202f%), et les duels de la tour et entre amis ne comptent plus la valeur d’épreuve',
  ui1007c:
    'Épreuves du temple\u202f: l’ingrédient principal et le secondaire sont maintenant deux cases au-dessus d’une liste d’ingrédients groupée par niveau, avec recherche\u202f; les niveaux inférieurs au plat sont repliés. Bons d’ingrédient de Frère 13\u202f: les niveaux sont des boutons qui indiquent combien de bons vous avez, les ingrédients qui manquent à votre rue et ceux que vous n’avez pas passent en premier, avec combien vous en avez et combien il en manque, et on choisit avec +',
  batch1007b:
    'Les échanges avec les amis passent à 10 par jour tous amis confondus, et chaque joueur peut être sollicité au plus 20 fois par jour, quel que soit le nombre d’étoiles (avec beaucoup d’étoiles, vous gardez au moins 3 échanges avec M. Krab)\u202f; les gemmes sont renommées par rang\u202f: pierre brute, spirituelle et divine, puis jade brut, spirituel et divin\u202f; une icône cadeau à côté de l’activité du jour sur l’accueil signale une récompense à récupérer\u202f; en classe, on peut filtrer les plats signature par niveau pour ouvrir un cours\u202f; le marché de luxe ferme pour l’instant\u202f; dans la boutique de la tour, les statues affichent «\u202f1 max\u202f» à la place de la quantité',
  parens1007:
    'Dans l’interface en chinois (y compris les descriptions d’objets et les noms de recettes), les parenthèses pleine chasse sont maintenant des parenthèses normales avec une espace de chaque côté, pour faire tenir plus de texte par ligne',
  ui1007:
    'Petits ajustements d’interface\u202f: À prendre ou à laisser liste maintenant les boîtes ouvertes à chaque manche et leur contenu\u202f; le «\u202fRécupérer\u202f» de la quête principale sur l’accueil est maintenant une icône cadeau avec du texte, et les boutons verts ailleurs prennent la couleur de la marque\u202f; les filtres par niveau et par voie des plats signature sont maintenant de petites pastilles\u202f; les plats signature ne sont plus dans «\u202fPlus\u202f»\u202f: on y accède depuis l’accueil',
  misc1007:
    'La discussion quotidienne avec Sœur Wen a déménagé de la place au bar\u202f; le Pack d’ingrédient universel au hasard ne donne plus qu’un ingrédient universel, et le Pack de départ offre aussi 10 ingrédients universels de niveau 1, 10 de niveau 2 et 5 de niveau 3\u202f; les cafards posés par des amis partent d’eux-mêmes au bout de 4 heures au plus\u202f; les ingrédients de niveau 6 ne peuvent plus être échangés à la bourse pour l’instant, et leurs ordres en cours sont retirés et rendus sur votre compte de bourse\u202f; la tâche «\u202fManger gratis\u202f» compte dès que vous commencez\u202f; le frigo affiche aussi le niveau de chaque ingrédient et combien il en faut encore pour votre rue\u202f; le remplissage d’huile utilise une icône de goutte',
  fix1007:
    'Une série de petits correctifs\u202f: dans les prédictions, les événements terminés affichent d’abord les plus récents\u202f; aux gobelets, les manches qui font les gros titres ou une annonce à toute la ville le font désormais à chaque fois (plus de limite d’une fois par jour), et le tableau des récompenses reste visible avec la manche en cours mise en évidence pendant que vous décidez\u202f; les descriptions des tables du Dernier bonbon suivent les vraies règles\u202f; la page «\u202fLes miens\u202f» des rachats indique que le dividende d’hier n’a pas encore été versé tant qu’il ne l’est pas\u202f; les liens de connexion quotidienne et de remplissage d’huile de l’accueil sont plus faciles à toucher\u202f; les liens de noms dans le texte sont soulignés au survol de la souris ou quand on les sélectionne au clavier',
  links1007:
    'Les liens texte de tout le jeu ressemblent désormais à ceux de l’accueil\u202f: couleur de la marque, sans soulignement, avec un «\u202f›\u202f» à la fin quand ils mènent à une autre page et un «\u202f‹\u202f» au début quand ils ramènent en arrière. Les actions sur la page même (renvoyer, actualiser, annuler, répondre) ont le même aspect que les liens, sans soulignement ni marge en plus',
  cup1007:
    'Le jeu des gobelets du bar change\u202f: jusqu’à 4 manches avec 2, 3, 5 puis 7 gobelets, et un dé sous un seul d’entre eux. Chaque fois que vous trouvez, vous pouvez vous arrêter et prendre la récompense de la manche, ou passer à la suivante\u202f; si vous vous trompez, vous repartez sans rien. Plus vous allez loin, plus la récompense est grande\u202f: s’arrêter dans les dernières manches fait les gros titres, et réussir toutes les manches rapporte de grosses récompenses et une annonce à toute la ville. Chaque partie coûte 1 bon mystère, sans hausse avec la série\u202f; la probabilité de trouver est d’une sur le nombre de gobelets (la chance aide toujours)',
  deal1007:
    'Nouveau jeu au bar, «\u202fÀ prendre ou à laisser\u202f»\u202f: 10 boîtes sur la table, chacune avec des ingrédients, la plus grosse avec cinq ingrédients universels de niveau 5. Choisissez votre boîte, puis ouvrez les autres manche après manche. Après chaque manche, le banquier de la ville propose des pièces pour votre boîte\u202f: acceptez et repartez, ou continuez d’ouvrir\u202f; si vous refusez jusqu’au bout, vous gardez le contenu de votre boîte. 10 000 pièces la partie, 3 parties par jour',
  spice1007:
    'Nouveau jeu au bar, «\u202fMélange secret\u202f»\u202f: le barman mélange 4 condiments parmi 10 dans un ordre précis. À chaque essai, vous donnez une combinaison et recevez une réponse en A et B (A\u202f: bon condiment à la bonne place\u202f; B\u202f: bon condiment à la mauvaise place). Vous avez jusqu’à 8 essais, et plus vous trouvez vite, meilleur est le prix\u202f: en 4 essais ou moins, gros prix, renommée et passage aux nouvelles. 2 bons mystère par partie, 5 parties par jour',
  nim1007:
    'Nouveau jeu au bar, «\u202fLe dernier bonbon\u202f»\u202f: à tour de rôle avec le barman, prenez quelques bonbons dans un tas (chaque table a sa limite)\u202f; celui qui prend le dernier gagne. La table débutants coûte 1 bon mystère, vous choisissez qui commence et le barman se trompe parfois\u202f; la table experts coûte 2 bons mystère, une pièce décide qui commence et le barman ne se trompe jamais. Une victoire donne de la renommée et un prix\u202f; 10 parties par jour pour les deux tables',
  homeLinks1007:
    'Accueil réorganisé\u202f: les liens texte ont tous la couleur de la marque, sans soulignement, et finissent par «\u202f›\u202f»\u202f; le pointage est un lien texte, une coche fine s’affiche une fois pointé et la ligne du cadeau disparaît\u202f; remettre de l’huile est une icône avec du texte au lieu d’un bouton\u202f; les raccourcis ustensiles, entrepôt et boutique sont remplacés par «\u202fRecettes apprises/total\u202f» et votre spécialité en vente\u202f; une nouvelle ligne «\u202fPatrimoine\u202f» indique la valeur totale des restaurants que vous possédez, avec un lien vers les Rachats\u202f; les nouveaux restaurants qui n’ont encore réglé aucun tour accèdent aussi à l’historique des gains et aux étages depuis l’accueil. Dans Plus, Inviter des amis (dans Mon compte), Météo (en haut à droite de l’accueil), Rachats, Étages et tables et Historique des gains disparaissent, Infos du restaurant passe dans Autres et «\u202fUstensiles et points\u202f» devient simplement «\u202fUstensiles\u202f»',
  npc1007:
    'La classe, les échanges et le Fonds de développement passent de la Place à la Guilde. Gros Mangeur, sur la Place, était en fait le maire\u202f: il s’appelle désormais Maire Grosse Marmite et se trouve à la Guilde, avec sa discussion quotidienne (un ingrédient et une graine), la question «\u202foù est le Garçon hip-hop\u202f» et l’échange d’objets rares. Frère 13 (klaxons quotidiens, bons d’ingrédients) et Carmen (bons d’ingrédients mystères, et un offert à la première visite) sont aussi à la Guilde\u202f; Gary gère le Fonds de développement. Le juge Gros Mangeur devient lui aussi le Maire Grosse Marmite. Le taoïste Fan apparaît à l’expertise du temple et Kai sur la page des événements\u202f: touchez-les pour une autre réplique. La Place garde Nouvelles, Habitants et Classements',
  duel1007:
    'Les résultats du duel culinaire se lisent désormais comme l’avis des juges\u202f: chaque juge passe en revue ses critères (victoire écrasante, au coude-à-coude ou déroute totale) et donne un score\u202f; le résultat montre aussi le plat spécial de chaque camp («\u202fPas de plat spécial\u202f» s’il n’y en a pas). Le juge Vieux Fauché est remplacé par Gordon, et Carmen par Joe',
  home1007:
    'Accueil plus compact\u202f: les pièces, l’EXP et l’huile du dernier tour s’affichent en icônes (celle de l’EXP est la même que sur votre barre d’EXP), avec l’historique des gains et les étages à droite de leurs lignes\u202f; un raccourci pour améliorer le bidon d’huile est à côté de votre huile\u202f; le pointage quotidien et les points d’activité partagent une ligne, et une coche apparaît une fois pointé. Les cartes, lignes et titres de tout le jeu sont un peu moins espacés, pour en voir plus à l’écran',
  acquire1006:
    'Nouvelle fonctionnalité «\u202fRachats\u202f» (dans Plus)\u202f: les restaurants de 2 étoiles ou plus ont une valorisation, et vous pouvez racheter le restaurant d’un autre à ce prix. L’ancien propriétaire reçoit 90\u202f% et 10\u202f% part en taxe. Les restaurants rachetés versent chaque jour un dividende à leur propriétaire\u202f; s’occuper du propriétaire une fois par jour vous rapporte 5 ingrédients et augmente son dividende de moitié. Vous pouvez racheter votre restaurant à sa valorisation, et les propriétaires peuvent le mettre en vente avec une remise ou le lâcher. La page des autres restaurants montre leur valorisation et leur propriétaire, et les rachats, achats en vente et rachats de soi-même de 10 000 000 pièces ou plus font les nouvelles',
  backlog8:
    'Dans le guide du wiki, le nombre de recettes de la Rue des débutants et de la plus grande rue, les recettes nécessaires pour 2 étoiles, les conditions de la vente à emporter et de la Bourse et le bonus d’EXP de départ suivent désormais les valeurs par défaut actuelles du jeu\u202f; les règles du duel indiquent aussi quels attributs compte chaque note selon les pondérations actuelles',
  perf1006:
    'Le site télécharge environ 140 Ko de moins au premier chargement (la police d’icônes ne contient que les icônes utilisées), et le Marché, le Bar, l’Ichiban Kuji, le Temple et la Place s’ouvrent plus vite',
  backlog7:
    'Le nom du restaurant de M. Krab et son message d’accueil s’affichent désormais dans votre langue\u202f; les pourcentages suivent le format de votre langue (virgule décimale et espace avant\u202f%), et le détail du taux de renforcement n’est plus collé au nombre\u202f; «\u202fnom × quantité\u202f» ne se coupe plus sur deux lignes sur les écrans étroits\u202f; si votre accès à la Bourse est gelé, la Bourse et les prédictions de l’activité du jour l’indiquent\u202f; la liste des recettes du wiki affiche au plus 1 000 entrées puis propose d’affiner par recherche ou par rue, et une rue inconnue dans l’adresse affiche toutes les recettes',
  backlog6:
    'Les règles du duel indiquent le nombre de juges réellement utilisé sur ce serveur\u202f; l’ustensile lâché par un ancien a sa propre ligne sur la carte de résultat et fait l’objet d’une nouvelle\u202f; l’échange d’éclats des plats signature permet d’en échanger plusieurs à la fois\u202f; le «\u202fComment l’obtenir\u202f» des objets d’expertise mentionne les coups critiques sur le gardien du Temple\u202f; les pages d’objets du wiki listent aussi la Promo du jour, le marché noir, les récompenses aléatoires et l’amélioration de gemmes comme sources',
  visual1006:
    'Corrections de mise en page sur mobile\u202f: le tableau des caractéristiques du détail d’ustensile a maintenant une ligne par caractéristique\u202f; les raisons de blocage dans l’activité du jour ont leur propre ligne\u202f; la liste déroulante d’échange d’éclats des plats signature ne déborde plus et affiche «\u202fChoisir un plat\u202f»\u202f; la liste des bonus actifs et les lignes de fragments passent à la ligne si besoin\u202f; la carte de résultat du duel affiche le nom traduit de l’ancien et les scores avec la virgule décimale',
  stealForget1006:
    'Rater l’espionnage d’un cours est moins sévère\u202f: au lieu d’oublier complètement (niveau du cours × 3 + 1) recettes au hasard, (niveau du cours × 2 + 1) recettes au hasard perdent 1 niveau de qualité, et seules celles de qualité Commun sont oubliées\u202f; pour les cours de niveau 4 et plus, le risque d’oublier aussi un plat signature de niveau inférieur passe de niveau × 5\u202f% à niveau × 2\u202f%',
  frTimes1006:
    'Les quantités d’objets suivent maintenant la typographie française, avec des espaces autour du × (par exemple «\u202fRiz × 3\u202f»)',
  web1006:
    'En échangeant des ingrédients avec vos amis ou M. Krab, vous pouvez chercher par nom, et ceux qui vous manquent pour vos recettes apparaissent en premier avec la quantité manquante\u202f; l’astuce pour changer de rue sur la page des recettes peut être masquée jusqu’à la prochaine étoile\u202f; «\u202fTout récupérer\u202f» pour les livraisons n’apparaît que si une commande est arrivée\u202f; toucher «\u202fRecettes\u202f» dans la barre du bas quand vous regardez une autre rue vous ramène à la vôtre\u202f; l’onglet du fonds de développement sur la place permet de réessayer si votre restaurant ne se charge pas',
  checks1006:
    'Dans l’activité du jour, la bourse et les prédictions indiquent s’il manque encore des jours depuis l’inscription ou la vérification de l’e-mail, «\u202fRécupérer les récompenses d’événement\u202f» apparaît comme indisponible quand aucun événement n’est en cours, et les livraisons affichent le nombre d’étoiles réellement exigé par ce serveur. Les pierres bleues et vertes de rang 6 comptent désormais comme rang 6 (elles coûtaient l’énergie et les frais de retrait d’un rang 5)',
  luckGem1006:
    'Nouvelle gemme, la Pierre du destin\u202f: sertissez-la pour gagner de la chance (rangs 1 à 6\u202f: +1, 2, 4, 8, 16, 24). Le rang 1 est vendu à la boutique (pièces), dans la Promo du jour et au marché noir, il tombe aussi des récompenses aléatoires et monte de rang comme les autres gemmes. Au bar, la chance au Chifoumi n’augmente plus que la probabilité de gagner, et il reste toujours au moins 10\u202f% de risque de perdre\u202f; avant, avec beaucoup de chance, on ne pouvait plus perdre',
  mcLearn1006:
    'Apprendre les plats signature est plus facile\u202f: décomposez les fragments inutiles en éclats, et 3 éclats d’un niveau donnent 1 fragment de n’importe quel plat de ce niveau. Le Sceau Délice réussit maintenant 40\u202f% du temps au lieu de 28\u202f%, et le Sceau de jade du Dieu de la cuisine est à la boutique (300 000). L’expertise du Temple indique comment obtenir chaque objet, et le guide a une section «\u202fComment apprendre les plats signature\u202f»',
  power1006:
    'La page de l’équipement affiche maintenant votre puissance d’attaque et de défense en duel (avec tous les bonus de Chance et ceux des ensembles), et la Tour des chefs indique «\u202fMa puissance d’attaque\u202f»\u202f: les deux pages concordent',
  mcTabs1006:
    'La page des plats signature a maintenant des onglets par niveau et par voie\u202f: choisissez un niveau en haut et une voie en bas, les plats appris et les fragments sont filtrés ensemble, avec le nombre sur chaque onglet. Votre choix est gardé pour la prochaine fois',
  gearIncome1006:
    'L’équipement porté (gemmes comprises) ajoute maintenant des pièces finales, de l’EXP finale et plus de chances d’obtenir des plats signature en or\u202f; plus les caractéristiques sont élevées, plus le bonus est grand (la Créativité compte le plus, la Chance ne compte pas), et la page de l’équipement indique combien. Les plats signature se vendent plus cher aux clients selon leur niveau (niveau 3 ×2,5, niveau 4 ×3,2), car ceux de niveau 2 à 5 ne remboursaient pas le prix de leurs ingrédients. Les duels culinaires utilisent toujours la valeur d’origine par portion',
  elders1006:
    'Les gardiens de la Tour des chefs sont maintenant des Anciens\u202f: chaque étage porte son propre équipement complet (+3 à +6) et les points d’attribut de son niveau, que vous pouvez déplier pour les voir. Une vraie victoire peut faire tomber une pièce de l’ensemble de l’Ancien (20\u202f% aux étages 1 à 3, moins plus haut). Les étages 1 et 2 sont un peu plus durs qu’avant et les étages 6 à 10 nettement plus faciles. Le bonus aléatoire de la Créativité dans les duels culinaires baisse un peu et ne vaut plus davantage que les autres attributs',
  duel1006:
    'Les duels culinaires (Tour des chefs, Classement des chefs et duels entre amis) sont maintenant départagés par des juges\u202f: à chaque duel, 5 des 10 juges sont tirés au sort, chacun regarde quelques-unes des cinq notes, et le premier camp à 3 voix gagne. De meilleurs attributs sont maintenant bien plus fiables\u202f; la Créativité et la Chance ajoutent un bonus aléatoire. Voir «\u202fRègles du duel culinaire\u202f» sur la page de la Tour des chefs',
  barPrize1006:
    'Gagner au bar au Chifoumi, aux Gobelets, au Cocktail Mémoire et aux Fléchettes rapporte maintenant surtout des ingrédients au lieu de petites sommes de pièces et d’EXP. Plus la victoire est difficile (série plus longue, niveau plus avancé, fléchettes parfaites), plus l’ingrédient est de haut niveau et plus il a de chances d’être rare',
  align1006:
    'L’étiquette du type de rue (pièces, équilibrée ou EXP) sur les pages des recettes et du déménagement est maintenant alignée avec le texte du bonus',
  krab1006:
    'Le garde-manger de M. Krab est maintenant bien rempli\u202f: tous les ingrédients de niveau 1 à 5, jusqu’à des centaines pour les plus courants et moins pour les rares, réapprovisionnés chaque jour. Le nombre d’échanges quotidiens avec M. Krab ne change pas',
  guide1006:
    'Le wiki du jeu a maintenant un guide de jeu\u202f: trois rythmes de jeu, quoi faire à chaque connexion, quand déménager et où dépenser ses pièces en premier. La page des recettes suggère de déménager quand votre rue n’a pas assez de recettes pour l’étoile suivante',
  batch9:
    'Chaque réassort du marché ajoute désormais un ingrédient dont ont besoin les recettes de la Rue des débutants (Treize épices, Tofu, Sucre candi…)\u202f: les nouveaux joueurs ne restent plus bloqués des jours. La page des recettes, la page de déménagement et le wiki du jeu indiquent si une rue est à pièces, équilibrée ou à EXP, et d’où vient son bonus',
  streets1005:
    'Bonus des rues rééquilibrés\u202f: les rues qui rapportent plus de pièces donnent moins d’EXP et inversement, et les revenus totaux des rues sont bien plus proches. Cela s’applique aussi aux restaurants déjà installés\u202f: les pièces baissent le plus rue du Guangdong et rues Fusion I et II, et l’EXP monte le plus rue du Shandong, rue de Grèce et rue Chop Suey (voir le bonus de rue sur la page de déménagement). Sous le niveau 40, l’EXP de chaque tour reçoit un bonus, +200\u202f% au niveau 1 et de moins en moins à chaque niveau\u202f: les nouveaux joueurs montent plus vite',
  hostLimit1005:
    'Chaque joueur ne peut désormais fouiller que quelques emplacements par restaurant et par jour, et écraser que quelques cafards par jour chez un même ami (pas de limite chez vous ni chez M. Krab). Le garde-manger et le restaurant de l’ami indiquent ce qu’il vous reste aujourd’hui',
  browse1005:
    'En revenant d’une recette ou d’une fiche du wiki, la rue, les filtres et la page sont conservés. La page des recettes affiche le bonus de la rue choisie. Toucher un cafard que vous avez posé indique que vous ne pouvez pas l’écraser vous-même',
  renumber1005:
    'Les objets, ingrédients et recettes ont été renumérotés par catégorie\u202f: les identifiants du wiki du jeu et de l’API ouverte ont changé, et les anciens liens du wiki redirigent vers les nouveaux. Vos objets, vos recettes apprises et votre historique ne changent pas',
  retire1005:
    "Wiki du jeu\u202f: 117 anciens objets impossibles à obtenir en jeu (ustensiles et médailles réservés à certains joueurs du jeu d'origine, un paquet de test et un ancien paquet de mise à jour) ne sont plus listés\u202f; ceux qui les possèdent déjà les gardent et peuvent toujours s'en servir",
  tasks1005:
    "Tâches\u202f: les activités soumises à un niveau (bourse, prédictions…) ou fermées sur ce serveur s'affichent verrouillées\u202f; la bulle de l'heure se ferme en touchant ailleurs\u202f; l'icône du courrier est alignée",
  looks1005:
    "Apparence\u202f: désormais, les portes achetées (et celle installée actuellement) vous appartiennent, y revenir est gratuit\u202f; les messages d'étoiles insuffisantes indiquent vos étoiles actuelles\u202f; le wiki indique les étoiles requises pour les affiches et trophées",
  visual1005:
    "Anglais, français et espagnol\u202f: le singulier et le pluriel suivent le nombre (1 pièce, 1 jour…)\u202f; sur mobile, les caractéristiques des ustensiles tiennent sur un écran, les effets météo ne sont plus répétés et les durées de plus d'un jour s'affichent en jours",
  perf1005:
    "La page d'accueil, les tâches et le badge des événements se chargent plus vite\u202f; le catalogue des objets n'est plus retéléchargé s'il n'a pas changé",
  rules1005:
    "Ichiban Kuji\u202f: le premier lot ouvert à minuit le 1er du mois prend le thème et les titres du nouveau mois\u202f; les remboursements du Fonds de développement sont arrondis plus précisément\u202f; une erreur au règlement du Pronostic du marché n'annule plus la question du marché dans Prédictions",
  wiki1005:
    'Wiki du jeu\u202f: les ustensiles affichent leurs bonus de set et les gemmes le nom du rang suivant\u202f; changer vite de page sur un réseau lent ne mélange plus les pages, et les erreurs de chargement sont signalées',
  fixes1005:
    'Petites corrections\u202f: la ligne du Maire se débloque seule à l’heure du Hip-hop Boy\u202f; les dépôts et retraits du Fonds apparaissent dans votre journal\u202f; les affiches et trophées pas encore utilisables sont grisés dans le choix des installations',
  posters:
    'La boutique ajoute 4 nouveaux niveaux d’affiches et de trophées du Dieu de la cuisine, disponibles dès 4, 6, 8 et 10★, pour des bonus de pièces et d’EXP qui suivent en fin de partie',
  scarcity:
    'Les ingrédients aléatoires ont une chance d’être justement ceux qui manquent à vos recettes, plus souvent avec une chance élevée\u202f; les récompenses du Bar et de la Tour peuvent donner des ingrédients rares',
  site: 'Ajout d’un journal des mises à jour et d’une page de liens\u202f; la barre du haut affiche l’heure',
  oilToast:
    'Chaque table occupée consomme au moins 1 huile\u202f; les messages s’affichent en haut et ne cachent plus les boutons',
  fund: 'Nouveau Fonds de développement sur la Place\u202f: déposez des pièces 7 jours, récupérez 90\u202f% plus une médaille d’EXP et un titre temporaire',
  kujiDeluxe:
    'L’Ichiban Kuji ajoute un tirage de luxe\u202f; le prix A et le dernier prix donnent le titre limité du mois',
  titleShop: 'Nouvelle boutique de titres dans Apparence\u202f: des titres temporaires contre des pièces',
  coinSink:
    'Économie\u202f: plats moins chers, ingrédients de haut niveau plus chers, des pièces pour monter en étoiles et déménager',
  newbiePack:
    'Pack de bienvenue et tickets d’ingrédient aléatoire niv. 1 à 5\u202f; les anciens restaurants l’obtiennent avec le code XINSHOULIBAO',
  wiki: 'Nouveau wiki du jeu\u202f: objets, ingrédients, recettes, ustensiles et rues',
  quests:
    'Quêtes refaites\u202f: chapitres, quêtes annexes et hebdomadaires, plus une liste du jour sur l’accueil',
  newStreets:
    '16 nouvelles rues étrangères et plus de mille recettes\u202f; on n’apprend que les plats de sa rue',
  languages: 'Disponible en chinois traditionnel, anglais, français et espagnol',
  craft: 'La fusion ne tire plus les ingrédients dont votre placard est déjà plein',
  home: 'Page d’accueil repensée',
  exchange:
    'Ouverture de la Bourse\u202f: échangez des ingrédients rares entre joueurs\u202f; les niv. 3 à 5 se vendent au système',
  predict:
    'Ouverture des prédictions\u202f: achetez et vendez des parts «\u202foui/non\u202f», réglées au résultat',
  kuji: 'Ouverture de l’Ichiban Kuji, avec des figurines limitées à thème chaque mois',
  activities:
    'Événements temporaires\u202f: objectifs, grille, passe de combat, échanges, objectifs et bonus de serveur',
};
export default changelog;
